export function PositionAbsolute({
  top = {{top}},
  left = {{left}},
  containerPositioned = {{containerPositioned}},
  background = "{{background}}",
}) {
  return (
    <div style={{ position: "relative", font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 320 }}
      role="img" aria-label="An absolutely positioned chip inside a box; when the box is not itself positioned, the chip escapes it and positions against the outer frame instead">
      <div style={{ position: "relative", height: 170, background: "#FAF7F2", border: "1.5px dashed #24143055", borderRadius: 8, padding: 10, boxSizing: "border-box" }}>
        <span style={{ position: "absolute", top: 4, left: 8, fontSize: 10, color: "#24143099" }}>outer frame (position: relative)</span>
        <div style={{ position: containerPositioned ? "relative" : "static", height: 100, marginTop: 18, background: "#BFD9F2", borderRadius: 6, boxSizing: "border-box" }}>
          <span style={{ display: "block", paddingTop: 6, padding: "6px 8px 0", fontSize: 10, color: "#241430aa" }}>
            inner box (position: {containerPositioned ? "relative" : "static"})
          </span>
          <div style={{ position: "absolute", top, left, padding: "8px 12px", borderRadius: 6, fontWeight: 700, boxShadow: "0 4px 10px rgba(36,20,48,.25)", background }}>
            chip
          </div>
        </div>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>
        position: absolute; top: {top}px; left: {left}px &mdash; positions against the nearest positioned ancestor
      </p>
    </div>
  );
}
